def d_cossearch():
    import math
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a)); nb = math.sqrt(sum(y * y for y in b))
        return dot / (na * nb)
    docs = {"d1": [1, 0, 1], "d2": [0, 1, 1], "d3": [1, 1, 0], "d4": [0, 0, 1], "d5": [1, 0, 0]}
    q = [1, 0, 1]
    ranked = sorted(docs.items(), key=lambda kv: cos(q, kv[1]), reverse=True)
    print("Cosine similarity of query [1,0,1]:")
    for k, v in ranked:
        print(f"  {k}: {cos(q, v):.3f}")
