def d_trie():
    trie = {}
    for w in ["print", "printf", "private", "proc"]:
        node = trie
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w
    def complete(pref):
        node = trie
        for ch in pref:
            node = node.get(ch, {})
        out = []
        def walk(nd):
            for k, v in nd.items():
                if k == "$": out.append(v)
                else: walk(v)
        walk(node); return out
