def d_varint():
    def enc(n):
        out = bytearray()
        while True:
            b = n & 0x7F; n >>= 7
            out.append(b | (0x80 if n else 0)); 
            if not n: break
        return bytes(out)
    def dec(bs):
        n = shift = 0
        for b in bs:
            n |= (b & 0x7F) << shift; shift += 7
            if not b & 0x80: break
        return n
    for n in (1, 127, 128, 300):
        print(f"  {n} -> {enc(n).hex()} ({len(enc(n))}B) -> {dec(enc(n))}")

