def d_mesh():
    import itertools
    nodes = ["A", "B", "C", "D"]
    edges = [("A", "B"), ("B", "C"), ("C", "D"), ("D", "A"), ("A", "C")]
    def paths(s, t, seen):
        if s == t: return [[t]]
        out = []
        for a, b in edges:
            nxt = b if a == s else (a if b == s else None)
            if nxt and nxt not in seen:
                for p in paths(nxt, t, seen | {nxt}):
                    out.append([s] + p)
        return out
    ps = paths("A", "C", {"A"})
