import heapq
def astar_demo():
    g={(0,0):0}; pq=[(5,(0,0))]; goal=(2,2); came={}
    while pq:
        _,u=heapq.heappop(pq)
        if u==goal: break
        for dx,dy in [(1,0),(0,1)]:
            v=(u[0]+dx,u[1]+dy)
            if v not in g:
                g[v]=g[u]+1; came[v]=u
                heapq.heappush(pq,(g[v]+abs(2-v[0])+abs(2-v[1]),v))
    path=[goal]
    while path[-1]!=(0,0): path.append(came[path[-1]])
    return list(reversed(path))
